-- C-071c: licensed photos for 11 of the 47 hotels added in C-071a (generated by
-- scripts/catalog/photos-sql.ts from scripts/catalog/photos-batch1.json).
alter table public.hotels add column if not exists image_source_url text;
update public.hotels h
set image_url = v.image_url, image_credit = v.image_credit, image_source_url = v.image_source_url
from (values
  ('mandarin-oriental-ritz-madrid', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Hotel_Ritz_%28Madrid%29_03.jpg/1280px-Hotel_Ritz_%28Madrid%29_03.jpg', 'Foto: Luis García ( Zaqarbal ), CC BY-SA 3.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hotel_Ritz_(Madrid)_03.jpg'),
  ('four-seasons-hotel-istanbul-at-sultanahmet', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d9/Four_Seasons_Sultanahmet_March_2008.JPG/1280px-Four_Seasons_Sultanahmet_March_2008.JPG', 'Foto: Gryffindor, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Four_Seasons_Sultanahmet_March_2008.JPG'),
  ('four-seasons-hotel-new-york', 'https://upload.wikimedia.org/wikipedia/commons/7/72/4_seasons_hotel_NY_56_jeh.jpg', 'Foto: Jim.henderson, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:4_seasons_hotel_NY_56_jeh.jpg'),
  ('the-ritz-carlton-new-york-central-park', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Ritz-Carlton_New_York%2C_Central_Park%2C_Manhattan%2C_New_York%2C_US.jpg/1280px-Ritz-Carlton_New_York%2C_Central_Park%2C_Manhattan%2C_New_York%2C_US.jpg', 'Foto: Clyde Charles Brown, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ritz-Carlton_New_York,_Central_Park,_Manhattan,_New_York,_US.jpg'),
  ('the-beverly-hills-hotel-los-angeles', 'https://upload.wikimedia.org/wikipedia/commons/1/19/BeverlyHillsHotel03.jpg', 'Foto: Minnaert, Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:BeverlyHillsHotel03.jpg'),
  ('the-peninsula-beverly-hills-los-angeles', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/The_Peninsula_Beverly_Hills_2015.jpg/1280px-The_Peninsula_Beverly_Hills_2015.jpg', 'Foto: Toglenn, CC BY-SA 3.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:The_Peninsula_Beverly_Hills_2015.jpg'),
  ('raffles-singapore', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/RafflesHotel-Singapore-20041025.jpg/1280px-RafflesHotel-Singapore-20041025.jpg', 'Foto: Velela ., Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:RafflesHotel-Singapore-20041025.jpg'),
  ('marina-bay-sands-singapur', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Marina_Bay_Sands_Hotel_3_%2831345110894%29.jpg/1280px-Marina_Bay_Sands_Hotel_3_%2831345110894%29.jpg', 'Foto: Tony Hisgett from Birmingham, UK, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Marina_Bay_Sands_Hotel_3_(31345110894).jpg'),
  ('rosewood-hong-kong', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Victoria_Dockside_night_view_201908.jpg/1280px-Victoria_Dockside_night_view_201908.jpg', 'Foto: Wpcpey, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Victoria_Dockside_night_view_201908.jpg'),
  ('park-hyatt-tokyo', 'https://upload.wikimedia.org/wikipedia/commons/7/7f/ParkHyattTokyo.JPG', 'Foto: moore, CC BY-SA 3.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:ParkHyattTokyo.JPG'),
  ('the-peninsula-shanghai', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/The_Peninsula_Shanghai.JPG/1280px-The_Peninsula_Shanghai.JPG', 'Foto: Livelikerw, CC BY-SA 3.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:The_Peninsula_Shanghai.JPG')
) as v (slug, image_url, image_credit, image_source_url)
where h.slug = v.slug;
